            "insert": "სასწავლო მიზნის დაწერა\", \"category\": \"todo\", \"image\": \"\", \"price\": 0}, {\"id\": \"type\", \"title\": \"CSS ბადის პრაქტიკა\", \"category\": \"doing\", \"image\": \"\", \"price\": 0}, {\"id\": \"audit\", \"title\": \"ინტერაქციის ტესტის დაწერა\", \"category\": \"todo\", \"image\": \"\", \"price\": 0}, {\"id\": \"photos\", \"title\": \"HTML სემანტიკის გამეორება\", \"category\": \"done\", \"image\": \"\", \"price\": 0}];\nlet hydrated=false;let state={items:initialItems.map(item=>({...item})),saved:[],cart:{}};\nfunction saveState(){}\nfunction render(){\n for(const status of ['todo','doing','done']){\n const column=document.getElementById(status);column.replaceChildren();\n state.items.filter(item=>item.category===status).forEach(item=>{\n const card=document.createElement('article');card.className='task-card';card.dataset.id=item.id;\n const tag=document.createElement('span');tag.className='task-tag';tag.textContent='გუნდის დავალება';\n const title=document.createElement('h4');title.textContent=item.title;\n card.append(tag,title);\n const next=document.createElement('button');next.type='button';next.dataset.next=item.id;next.textContent=status==='done'?'დაბრუნება':'შემდეგ ეტაპზე →';\n const remove=document.createElement('button');remove.type='button';remove.dataset.delete=item.id;remove.textContent='წაშლა';\n card.append(next,remove);column.append(card);\n });document.querySelector('[data-count=\"'+status+'\"]').textContent=state.items.filter(item=>item.category===status).length;\n }saveState();\n}\ndocument.querySelector('#task-form').addEventListener('submit',event=>{event.preventDefault();const input=document.querySelector('#task-title');const title=input.value.trim();if(title.length<3||title.length>100){document.querySelector('#task-error').textContent='დაწერე 3–100 სიმბოლო.';return;}state.items.push({id:(crypto.randomUUID?.()??Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16)).join('-')),title,category:'todo',image:'',price:0});input.value='';document.querySelector('#task-error').textContent='დავალება დაემატა.';render();});\nrender();\n\ndocument.querySelector('.kanban').addEventListener('click',event=>{const next=event.target.closest('[data-next]');const remove=event.target.closest('[data-delete]');if(next){const item=state.items.find(item=>item.id===next.dataset.next);const statuses=['todo','doing','done'];item.category=statuses[(statuses.indexOf(item.category)+1)%3];render();}if(remove){state.items=state.items.filter(item=>item.id!==remove.dataset.delete);render();}});\ndocument.querySelector('#request-form').addEventListener('submit',event=>{\n event.preventDefault();const form=event.currentTarget;const status=document.querySelector('#form-status');\n const name=form.elements.namedItem('name').value.trim();\n const email=form.elements.namedItem('email').value.trim();\n const message=form.elements.namedItem('message').value.trim();\n if(name.length<2||message.length<10||!form.checkValidity()){status.textContent='შეავსე სახელი, სწორი ელფოსტა და მინიმუმ 10-სიმბოლოიანი შეტყობინება.';return;}\n status.textContent='დემო მზადაა: '+name+', მონაცემები შემოწმებულია. შეტყობინება არ გაგზავნილა.';\n});\nfunction validState(value){\n if(!value||!Array.isArray(value.items)||value.items.length>500||!Array.isArray(value.saved)||!value.cart||typeof value.cart!=='object'||Array.isArray(value.cart))return false;\n const allowedCategories=[\"todo\", \"doing\", \"done\"];\n return value.items.every(item=>item&&typeof item.id==='string'&&item.id.length<100&&typeof item.title==='string'&&item.title.length<=100&&allowedCategories.includes(item.category)&&typeof item.image==='string'&&(/^\\/?photos\\/[a-z-]+\\.jpg$/.test(item.image)||item.image==='')&&Number.isFinite(item.price)&&item.price>=0&&item.price<=1000000)&&new Set(value.items.map(item=>item.id)).size===value.items.length&&value.saved.every(id=>typeof id==='string'&&value.items.some(item=>item.id===id))&&Object.entries(value.cart).every(([id,n])=>value.items.some(item=>item.id===id)&&Number.isInteger(n)&&n>0&&n<=999);\n}\nfunction saveState(){if(!hydrated)return;try{localStorage.setItem('firstlight-transfer-tempo-v2',JSON.stringify(state));document.querySelector('#storage-status').textContent='შენახულია ამ ბრაუზერში';}catch{document.querySelector('#storage-status').textContent='შენახვა მიუწვდომელია; სესია მაინც მუშაობს.';}}\ntry{const raw=localStorage.getItem('firstlight-transfer-tempo-v2');if(raw){const restored=JSON.parse(raw);if(validState(restored))state=restored;}}catch{/* ცუდი მონაცემით აპს არ ვაჩერებთ. */}\nhydrated=true;render();\nsaveState();\ndocument.querySelector(\"#clear-done\").addEventListener(\"click\",()=>{const count=state.items.filter(item=>item.category===\"done\").length;state.items=state.items.filter(item=>item.category!==\"done\");render();document.querySelector(\"#cleanup-status\").textContent=count+\" დასრულებული დავალება წაიშალა.\";});\n// დამოუკიდებელი ვერსიის საცავი ცალკეა."
