            "insert": "ფრილანსერის პირველი შეკვეთა\", \"category\": \"მიმდინარე\", \"image\": \"/photos/plant-leaf.jpg\", \"price\": 1200}, {\"id\": \"site\", \"title\": \"ლოკალური ბიზნესის კატალოგი\", \"category\": \"მიმდინარე\", \"image\": \"/photos/architecture.jpg\", \"price\": 2400}, {\"id\": \"catalog\", \"title\": \"რესტორნის მენიუ\", \"category\": \"დასრულებული\", \"image\": \"/photos/tbilisi-night.jpg\", \"price\": 800}];\nlet hydrated=false;let state={items:initialItems.map(item=>({...item})),saved:[],cart:{}};\nfunction saveState(){}\nfunction summarize(items){return {count:items.length,budget:items.reduce((sum,item)=>sum+item.price,0),active:items.filter(item=>item.category==='მიმდინარე').length};}\nfunction render(){\n const summary=summarize(state.items);document.querySelector('#total-budget').textContent=summary.budget+' ₾';document.querySelector('#active-count').textContent=summary.active;document.querySelector('#project-count').textContent=summary.count;\n const status=document.querySelector('#status-filter').value;const query=document.querySelector('#search').value.trim().toLocaleLowerCase();\n let items=state.items.filter(item=>(status==='ყველა'||item.category===status)&&item.title.toLocaleLowerCase().includes(query));\n if(document.querySelector('#sort').value==='budget')items=[...items].sort((a,b)=>b.price-a.price);\n const body=document.querySelector('#records');body.replaceChildren();\n items.forEach(item=>{const row=document.createElement('tr');row.dataset.id=item.id;const name=document.createElement('td');const wrap=document.createElement('div');wrap.className='project-name';const image=document.createElement('img');image.src=item.image;image.alt='';image.width=38;image.height=38;const title=document.createElement('strong');title.textContent=item.title;wrap.append(image,title);name.append(wrap);\n const status=document.createElement('td');const badge=document.createElement('span');badge.className='badge'+(item.category==='დასრულებული'?' done':'');badge.textContent=item.category;status.append(badge);\n const price=document.createElement('td');price.className='price';price.textContent=item.price+' ₾';const action=document.createElement('td');const button=document.createElement('button');button.type='button';button.dataset.remove=item.id;button.textContent='წაშლა';button.setAttribute('aria-label','წაშალე '+item.title);action.append(button);row.append(name,status,price,action);body.append(row);});\n const empty=document.querySelector('#empty-state');if(empty)empty.hidden=items.length>0;saveState();\n}\nfor(const id of ['status-filter','sort','search'])document.getElementById(id).addEventListener('input',render);\nrender();\n\nconst detail=document.querySelector('#detail-dialog');\ndocument.querySelector('#dialog-close').addEventListener('click',()=>detail.close());\ndocument.querySelector('#add-record').addEventListener('click',()=>detail.showModal());\ndocument.querySelector('#record-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;const title=form.elements.namedItem('title').value.trim();const price=Number(form.elements.namedItem('budget').value);if(title.length<3||title.length>100||!Number.isFinite(price)||price<1||price>1000000){document.querySelector('#record-error').textContent='შეამოწმე სახელი და ბიუჯეტი (1–1 000 000 ₾).';return;}state.items.push({id:(crypto.randomUUID?.()??Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16)).join('-')),title,price,category:'მიმდინარე',image:'/photos/desk-tools.jpg'});render();form.reset();detail.close();document.querySelector('#record-status').textContent='პროექტი დაემატა.';});\ndocument.querySelector('#records').addEventListener('click',event=>{const button=event.target.closest('[data-remove]');if(button){state.items=state.items.filter(item=>item.id!==button.dataset.remove);render();document.querySelector('#record-status').textContent='პროექტი წაიშალა.';}});\ndocument.querySelector('#request-form').addEventListener('submit',event=>{\n event.preventDefault();const form=event.currentTarget;const status=document.querySelector('#form-status');\n const name=form.elements.namedItem('name').value.trim();\n const email=form.elements.namedItem('email').value.trim();\n const message=form.elements.namedItem('message').value.trim();\n if(name.length<2||message.length<10||!form.checkValidity()){status.textContent='შეავსე სახელი, სწორი ელფოსტა და მინიმუმ 10-სიმბოლოიანი შეტყობინება.';return;}\n status.textContent='დემო მზადაა: '+name+', მონაცემები შემოწმებულია. შეტყობინება არ გაგზავნილა.';\n});\nfunction validState(value){\n if(!value||!Array.isArray(value.items)||value.items.length>500||!Array.isArray(value.saved)||!value.cart||typeof value.cart!=='object'||Array.isArray(value.cart))return false;\n const allowedCategories=[\"მიმდინარე\", \"დასრულებული\"];\n return value.items.every(item=>item&&typeof item.id==='string'&&item.id.length<100&&typeof item.title==='string'&&item.title.length<=100&&allowedCategories.includes(item.category)&&typeof item.image==='string'&&(/^\\/?photos\\/[a-z-]+\\.jpg$/.test(item.image)||item.image==='')&&Number.isFinite(item.price)&&item.price>=0&&item.price<=1000000)&&new Set(value.items.map(item=>item.id)).size===value.items.length&&value.saved.every(id=>typeof id==='string'&&value.items.some(item=>item.id===id))&&Object.entries(value.cart).every(([id,n])=>value.items.some(item=>item.id===id)&&Number.isInteger(n)&&n>0&&n<=999);\n}\nfunction saveState(){if(!hydrated)return;try{localStorage.setItem('firstlight-transfer-orbit-v2',JSON.stringify(state));document.querySelector('#storage-status').textContent='შენახულია ამ ბრაუზერში';}catch{document.querySelector('#storage-status').textContent='შენახვა მიუწვდომელია; სესია მაინც მუშაობს.';}}\ntry{const raw=localStorage.getItem('firstlight-transfer-orbit-v2');if(raw){const restored=JSON.parse(raw);if(validState(restored))state=restored;}}catch{/* ცუდი მონაცემით აპს არ ვაჩერებთ. */}\nhydrated=true;render();\nsaveState();\nstate.items.push({id:'transfer-four',title:'მეოთხე დამოუკიდებელი შეკვეთა',category:'მიმდინარე',image:'/photos/desk-tools.jpg',price:1650});render();\n// დამოუკიდებელი ვერსიის საცავი ცალკეა."
